tools.example:
Application Library: Particle_Tracing_Module/Charged_Particle_Tracing/electron_beam_divergence (Electron Beam Divergence Due to Self-Potential), childs_law_benchmark and planar_diode.
// equivalent manual setup
model.component("comp1").physics().create("es", "Electrostatics", "geom1");
model.component("comp1").physics().create("cpt", "ChargedParticleTracing", "geom1");
model.component("comp1").physics("cpt").prop("ParticleReleaseSpecification").set("ParticleReleaseSpecification", "SpecifyCurrent");
// then Multiphysics > Electric Particle Field Interaction and Study > Bidirectionally Coupled Particle Tracing

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
model.component("comp1").physics().create("fpt", "FluidParticleTracing", "geom1");
model.component("comp1").physics("fpt").prop("ParticleReleaseSpecification").set("ParticleReleaseSpecification", "SpecifyMassFlowRate");
model.component("comp1").physics("fpt").create("df1", "DragForce", 3);
// add Multiphysics > Fluid-Particle Interaction, then Study > Bidirectionally Coupled Particle Tracing

model.component("comp1").physics().create("fpt", "DropletSprays", "geom1");
// defaults: Drag Force (df1) and Droplet Breakup (dr1) with Kelvin-Helmholtz subnode
// add a Nozzle (global) release and Droplet Evaporation as needed

model.component("comp1").physics().create("fpt", "FluidParticleTracing", "geom1");
model.component("comp1").physics("fpt").prop("Formulation").set("Formulation", "NewtonianIgnoreInertialTerms");
model.component("comp1").physics("fpt").prop("ParticleSizeDistribution").set("ParticleSizeDistribution", "SpecifyParticleDiameter");
model.component("comp1").physics("fpt").prop("StoreParticleStatusData").set("StoreParticleStatusData", "1");

model.component("comp1").physics("cpt").feature("pp1").set("mp", "40[u]");
model.component("comp1").physics("cpt").feature("pp1").set("Z", "1");  // singly charged Ar+ ion
model.component("comp1").physics("cpt").create("pp2", "ParticleProperties", 3);  // second species (electrons)

model.component("comp1").physics("cpt").create("rel1", "Release", 3);
model.component("comp1").physics("cpt").feature("rel1").selection().set(1);
model.component("comp1").physics("cpt").feature("rel1").set("InitialPosition", "RandomPosition");
model.component("comp1").physics("cpt").feature("rel1").set("N", 5000);
model.component("comp1").physics("cpt").feature("rel1").set("VelocitySpecification", "Maxwellian");
model.component("comp1").physics("cpt").feature("rel1").set("T0", "300[K]");

model.component("comp1").physics("fpt").create("inl1", "Inlet", 2);
model.component("comp1").physics("fpt").feature("inl1").selection().set(1);
model.component("comp1").physics("fpt").feature("inl1").set("InitialPosition", "Density");
model.component("comp1").physics("fpt").feature("inl1").set("dpro", "spf.U");  // release proportional to flow speed
model.component("comp1").physics("fpt").feature("inl1").set("N", 1000);
model.component("comp1").physics("fpt").feature("inl1").set("v0", new String[]{"u", "v", "w"});

model.component("comp1").physics("cpt").create("redg1", "ReleaseFromEdge", 1);
model.component("comp1").physics("cpt").feature("redg1").selection().set(12);
model.component("comp1").physics("cpt").feature("redg1").set("InitialPosition", "UniformDistribution");
model.component("comp1").physics("cpt").feature("redg1").set("N", 200);

model.component("comp1").physics("fpt").create("rpt1", "ReleaseFromPoint", 0);
model.component("comp1").physics("fpt").feature("rpt1").selection().set(5);
model.component("comp1").physics("fpt").feature("rpt1").set("InitialVelocity", "ConstantSpeedCone");
model.component("comp1").physics("fpt").feature("rpt1").set("Us", "20[m/s]");
model.component("comp1").physics("fpt").feature("rpt1").set("Nvel", 100);

model.component("comp1").physics("cpt").create("relg1", "ReleaseGrid", -1);
model.component("comp1").physics("cpt").feature("relg1").set("x0", new String[]{"range(0,1e-3,1e-2)", "0", "0"});
model.component("comp1").physics("cpt").feature("relg1").set("v0", new String[]{"0", "0", "1e6"});
// Application Library: incense_stick, ion_cyclotron_motion, trapped_protons use Release from Grid

model.component("comp1").physics("cpt").create("pbeam1", "ParticleBeam", 2);
model.component("comp1").physics("cpt").feature("pbeam1").selection().set(3);
model.component("comp1").physics("cpt").feature("pbeam1").set("El", "10[keV]");
model.component("comp1").physics("cpt").feature("pbeam1").set("e1rms", "1e-6[m]");
model.component("comp1").physics("cpt").feature("pbeam1").set("twbeta0", "0.1[m]");
// Application Library: einzel_lens, electron_beam_divergence, sensitive_high_resolution_ion_microprobe

model.component("comp1").physics("cpt").create("te1", "ThermionicEmission", 2);
model.component("comp1").physics("cpt").feature("te1").selection().set(4);
model.component("comp1").physics("cpt").feature("te1").set("T", "2000[K]");
model.component("comp1").physics("cpt").feature("te1").set("Phim", "4.5[V]");
// Application Library: Particle_Tracing_Module/Charged_Particle_Tracing/planar_diode

model.component("comp1").physics().create("fpt", "DropletSprays", "geom1");
model.component("comp1").physics("fpt").create("noz1", "NozzleGrid", -1);
// Nozzle Domain subnode is created automatically; select the gas domain in it

// particles larger than 1 um stick to a filter screen, smaller ones pass
model.component("comp1").physics("fpt").create("wall2", "Wall", 2);
model.component("comp1").physics("fpt").feature("wall2").selection().set(7);
model.component("comp1").physics("fpt").feature("wall2").set("WallCondition", "Stick");
model.component("comp1").physics("fpt").feature("wall2").set("PrimaryParticleCondition", "Expression");
model.component("comp1").physics("fpt").feature("wall2").set("e", "fpt.dp>1[um]");
model.component("comp1").physics("fpt").feature("wall2").set("Otherwise", "Pass");

model.component("comp1").physics("cpt").feature("wall1").create("sem1", "SecondaryEmission", 2);
model.component("comp1").physics("cpt").feature("wall1").feature("sem1").set("Ns", "2");
model.component("comp1").physics("cpt").feature("wall1").feature("sem1").set("InitialVelocity", "IsotropicHemisphere");
// Application Library: Particle_Tracing_Module/Charged_Particle_Tracing/multipactor_saturation

model.component("comp1").physics("pt").create("tre1", "ThermalReEmission", 2);
model.component("comp1").physics("pt").feature("tre1").selection().set(2, 3, 4);
model.component("comp1").physics("pt").feature("tre1").set("T", "293.15[K]");
// Application Library: Particle_Tracing_Module/Vacuum_Systems/s_bend_benchmark and rf_coupler

model.component("comp1").physics("cpt").create("pc1", "PeriodicCondition", 2);
model.component("comp1").physics("cpt").feature("pc1").selection().set(1, 6);
// Application Library: Particle_Tracing_Module/Charged_Particle_Tracing/multipactor_saturation

model.component("comp1").physics("pt").create("vre1", "VelocityReinitialization", 3);
model.component("comp1").physics("pt").feature("vre1").selection().all();
model.component("comp1").physics("pt").feature("vre1").set("SpecifyReinitializationTime", "1");
model.component("comp1").physics("pt").feature("vre1").set("tr", "1[us]");
model.component("comp1").physics("pt").feature("vre1").set("vr", new String[]{"-pt.vx", "-pt.vy", "-pt.vz"});  // reverse all particles at t = 1 us
// Application Library: Particle_Tracing_Module/Charged_Particle_Tracing/trapped_protons

model.component("comp1").physics("pt").feature("wall1").create("bacc1", "BoundaryAccumulator", 2);
model.component("comp1").physics("pt").feature("wall1").feature("bacc1").set("AccumulatedVariableName", "nhits");
model.component("comp1").physics("pt").feature("wall1").feature("bacc1").set("R", "1");
// plot pt.wall1.bacc1.nhits on the wall boundaries

model.component("comp1").physics("cpt").create("dacc1", "DomainAccumulator", 3);
model.component("comp1").physics("cpt").feature("dacc1").selection().all();
model.component("comp1").physics("cpt").feature("dacc1").set("AccumulateOver", "ElementsAndTime");
model.component("comp1").physics("cpt").feature("dacc1").set("R", "cpt.Ep");  // deposited kinetic energy

model.component("comp1").physics("pt").create("pcnt1", "ParticleCounter", 2);
model.component("comp1").physics("pt").feature("pcnt1").selection().set(9);
// Global Evaluation of pt.pcnt1.alpha gives the transmission probability
// Application Library: s_bend_benchmark, brownian_motion, tubular_centrifuge

model.component("comp1").physics("fpt").create("aux1", "AuxiliaryField", 3);
model.component("comp1").physics("fpt").feature("aux1").selection().all();
model.component("comp1").physics("fpt").feature("aux1").set("fieldVariableName", "tres");
model.component("comp1").physics("fpt").feature("aux1").set("R", "1");  // residence time
// Application Library: ion_range_benchmark, trapped_protons

model.component("comp1").physics("pt").create("for1", "Force", 3);
model.component("comp1").physics("pt").feature("for1").selection().all();
model.component("comp1").physics("pt").feature("for1").set("F", new String[]{"0", "0", "-pt.mp*g_const"});

model.component("comp1").physics("cpt").create("ppi1", "ParticleParticleInteraction", 3);
model.component("comp1").physics("cpt").feature("ppi1").selection().all();
model.component("comp1").physics("cpt").feature("ppi1").set("InteractionForce", "Coulomb");
// Application Library: Particle_Tracing_Module/Verification_Examples/three_body_problem

model.component("comp1").physics("fpt").feature("wall1").create("ero1", "Erosion", 2);
model.component("comp1").physics("fpt").feature("wall1").feature("ero1").set("ErosionModel", "DNV");
// Application Library: Particle_Tracing_Module/Fluid_Flow/pipe_elbow_erosion

model.component("comp1").physics("fpt").prop("StoreParticleStatusData").set("StoreParticleStatusData", "1");
model.result().numerical().create("gev1", "EvalGlobal");
model.result().numerical("gev1").set("expr", new String[]{"fpt.fst"});  // fraction stuck = capture efficiency
